1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"syscall"
14	)
15	
16	// Block is one validated, deduplicated input block. Swaps are kept in
17	// canonical order: exact duplicates removed, sorted by Index.
18	type Block struct {
19		ChainID     string
20		BlockHash   string
21		BlockNumber int64
22		Swaps       []Swap
23	}
24	
25	// ReportFinding is one risk conclusion inside a block report. Evidence
26	// carries the raw fields of every swap that participated in the judgment.
27	type ReportFinding struct {
28		Kind     string `json:"kind"`
29		Severity int    `json:"severity"`
30		TxHash   string `json:"txHash"`
31		Evidence []Swap `json:"evidence"`
32	}
33	
34	// Report is the archived per-block risk report. Version records the full
35	// rule parameters that produced the findings, so the report stays
36	// interpretable without the original rule definition.
37	type Report struct {
38		ChainID     string          `json:"chainId"`
39		BlockHash   string          `json:"blockHash"`
40		BlockNumber int64           `json:"blockNumber"`
41		SwapCount   int             `json:"swapCount"`
42		Version     RuleVersion     `json:"version"`
43		Findings    []ReportFinding `json:"findings"`
44	}
45	
46	// LineError pins a replay failure to a 1-based input line.
47	type LineError struct {
48		Line int
49		Err  error
50	}
51	
52	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
53	func (e *LineError) Unwrap() error { return e.Err }
54	
55	// ErrBusy reports an archive locked by another process.
56	var ErrBusy = errors.New("archive is busy")
57	
58	// ErrUnknownBlock reports a query for a block that was never archived.
59	var ErrUnknownBlock = errors.New("unknown block")
60	
61	type blockID struct {
62		chainID   string
63		blockHash string
64	}
65	
66	// swapLine mirrors one swap record inside a block line. Pointers
67	// distinguish a missing field (or an explicit null) from an explicit
68	// zero value: a replay record must be complete on its own, so In, Out,
69	// GasPrice and Index are all required and may not be null.
70	type swapLine struct {
71		TxHash   *string `json:"TxHash"`
72		Pool     *string `json:"Pool"`
73		Trader   *string `json:"Trader"`
74		In       *int64  `json:"In"`
75		Out      *int64  `json:"Out"`
76		GasPrice *int64  `json:"GasPrice"`
77		Index    *int    `json:"Index"`
78	}
79	
80	// blockLine mirrors one input line. Pointers distinguish a missing field
81	// from an explicit zero value.
82	type blockLine struct {
83		ChainID     *string     `json:"chainId"`
84		BlockHash   *string     `json:"blockHash"`
85		BlockNumber *int64      `json:"blockNumber"`
86		Swaps       *[]swapLine `json:"swaps"`
87	}
88	
89	func parseBlock(text string) (Block, error) {
90		var raw blockLine
91		dec := json.NewDecoder(strings.NewReader(text))
92		if err := dec.Decode(&raw); err != nil {
93			return Block{}, fmt.Errorf("invalid JSON: %w", err)
94		}
95		if dec.More() {
96			return Block{}, errors.New("invalid JSON: unexpected trailing data")
97		}
98		if raw.ChainID == nil || *raw.ChainID == "" {
99			return Block{}, errors.New("chainId must be a non-empty string")
100		}
101		if raw.BlockHash == nil || *raw.BlockHash == "" {
102			return Block{}, errors.New("blockHash must be a non-empty string")
103		}
104		if raw.BlockNumber == nil {
105			return Block{}, errors.New("blockNumber is required")
106		}
107		if *raw.BlockNumber < 0 {
108			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
109		}
110		if raw.Swaps == nil {
111			return Block{}, errors.New("swaps must be an array")
112		}
113	
114		byTx := make(map[string]Swap)
115		byIndex := make(map[int]string)
116		swaps := []Swap{}
117		for i, s := range *raw.Swaps {
118			if s.TxHash == nil || *s.TxHash == "" {
119				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
120			}
121			if s.Pool == nil || *s.Pool == "" {
122				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
123			}
124			if s.Trader == nil || *s.Trader == "" {
125				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
126			}
127			// Every numeric field must be present and non-null in this very
128			// record; an explicit zero is a valid value, never a missing one.
129			// Values must not be borrowed from a neighbour, a same-hash record
130			// or a default, so an incomplete record is rejected before dedup
131			// even when a complete record with the same tx hash exists.
132			for _, f := range []struct {
133				name string
134				v    *int64
135			}{
136				{"In", s.In}, {"Out", s.Out}, {"GasPrice", s.GasPrice},
137			} {
138				if f.v == nil {
139					return Block{}, fmt.Errorf("swaps[%d]: %s is required and must not be null", i, f.name)
140				}
141			}
142			if s.Index == nil {
143				return Block{}, fmt.Errorf("swaps[%d]: Index is required and must not be null", i)
144			}
145			in, out, gasPrice, index := *s.In, *s.Out, *s.GasPrice, *s.Index
146			if in < 0 || out < 0 || gasPrice < 0 || index < 0 {
147				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
148			}
149			swap := Swap{
150				TxHash: *s.TxHash, Pool: *s.Pool, Trader: *s.Trader,
151				In: in, Out: out, GasPrice: gasPrice, Index: index,
152			}
153			if prev, ok := byTx[swap.TxHash]; ok {
154				if prev != swap {
155					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, swap.TxHash)
156				}
157				continue // exact duplicate, keep one copy
158			}
159			if other, ok := byIndex[swap.Index]; ok {
160				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, swap.Index, other)
161			}
162			byTx[swap.TxHash] = swap
163			byIndex[swap.Index] = swap.TxHash
164			swaps = append(swaps, swap)
165		}
166		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
167		return Block{
168			ChainID:     *raw.ChainID,
169			BlockHash:   *raw.BlockHash,
170			BlockNumber: *raw.BlockNumber,
171			Swaps:       swaps,
172		}, nil
173	}
174	
175	func swapsEqual(a, b []Swap) bool {
176		if len(a) != len(b) {
177			return false
178		}
179		for i := range a {
180			if a[i] != b[i] {
181				return false
182			}
183		}
184		return true
185	}
186	
187	// sameContent reports whether two blocks carry the same content. Both sides
188	// are canonical (deduplicated, sorted by Index), so ordering and exact
189	// duplicates in the input do not affect the comparison.
190	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
191		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
192	}
193	
194	// DetectBlock checks every swap against its adjacent neighbours within its
195	// pool under the built-in rules. See DetectBlockWithRules.
196	func DetectBlock(swaps []Swap) []ReportFinding {
197		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
198	}
199	
200	// DetectBlockWithRules checks every swap against its adjacent neighbours
201	// within its pool under the given rule version: a sandwich when the same
202	// trader brackets the victim with higher gas on both sides, otherwise a
203	// displacement when the previous swap's gas strictly exceeds the configured
204	// multiple of the victim's. The last swap of a pool is checked too. An
205	// enabled sandwich takes priority over displacement for the same victim;
206	// with the sandwich rule off the victim can still be flagged for
207	// displacement. With both rules off the result is an empty slice. The
208	// judgment itself is shared with Detect; this entry only adds the block
209	// report's raw-swap evidence and ordering.
210	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
211		pools := make(map[string][]Swap)
212		for _, s := range swaps {
213			pools[s.Pool] = append(pools[s.Pool], s)
214		}
215		findings := []ReportFinding{}
216		for _, pool := range pools {
217			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
218			for i, victim := range pool {
219				var front, back *Swap
220				if i > 0 {
221					front = &pool[i-1]
222				}
223				if i+1 < len(pool) {
224					back = &pool[i+1]
225				}
226				j, hit := judgeVictim(front, victim, back, rules)
227				if !hit {
228					continue
229				}
230				// The evidence keeps the full swap fields of every record that
231				// participated: front, victim, and for a sandwich also back.
232				evidence := []Swap{*front, victim}
233				if j.kind == "sandwich" {
234					evidence = append(evidence, *back)
235				}
236				findings = append(findings, ReportFinding{
237					Kind: j.kind, Severity: j.severity, TxHash: victim.TxHash,
238					Evidence: evidence,
239				})
240			}
241		}
242		sort.Slice(findings, func(i, j int) bool {
243			if findings[i].Severity != findings[j].Severity {
244				return findings[i].Severity > findings[j].Severity
245			}
246			return findings[i].TxHash < findings[j].TxHash
247		})
248		return findings
249	}
250	
251	// record is the archived form of a block: the report plus the canonical
252	// swaps, so a later import can detect content conflicts. Version carries
253	// the full rule parameters used for the findings; it is nil only in
254	// archives written before rule versions existed, which are interpreted
255	// under the built-in rules.
256	type record struct {
257		ChainID     string          `json:"chainId"`
258		BlockHash   string          `json:"blockHash"`
259		BlockNumber int64           `json:"blockNumber"`
260		Swaps       []Swap          `json:"swaps"`
261		Findings    []ReportFinding `json:"findings"`
262		Version     *RuleVersion    `json:"version,omitempty"`
263	}
264	
265	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
266	
267	func (r record) ruleVersion() RuleVersion {
268		if r.Version != nil {
269			return *r.Version
270		}
271		return BuiltinVersion()
272	}
273	
274	func (r record) report() Report {
275		return Report{
276			ChainID:     r.ChainID,
277			BlockHash:   r.BlockHash,
278			BlockNumber: r.BlockNumber,
279			SwapCount:   len(r.Swaps),
280			Version:     r.ruleVersion(),
281			Findings:    r.Findings,
282		}
283	}
284	
285	const (
286		archiveFileName = "archive.json"
287		lockFileName    = "lock"
288	)
289	
290	type archiveData struct {
291		Records []record `json:"records"`
292		// Versions and EnabledVersion are absent in archives written before
293		// rule versions existed; such archives run the built-in rules.
294		Versions       []RuleVersion `json:"versions,omitempty"`
295		EnabledVersion string        `json:"enabledVersion,omitempty"`
296		// Suppressions and AlertRecords are absent in archives written before
297		// offline alerting existed; such archives simply have no registered
298		// conditions and no processing history.
299		Suppressions []Suppression      `json:"suppressions,omitempty"`
300		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
301		// Reviews is absent in archives written before manual reviews existed;
302		// every conclusion then behaves as unreviewed.
303		Reviews []ReviewObject `json:"reviews,omitempty"`
304	}
305	
306	func readArchive(dir string) (archiveData, error) {
307		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
308		if errors.Is(err, os.ErrNotExist) {
309			return archiveData{Records: []record{}}, nil
310		}
311		if err != nil {
312			return archiveData{}, err
313		}
314		var data archiveData
315		if err := json.Unmarshal(raw, &data); err != nil {
316			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
317		}
318		return data, nil
319	}
320	
321	// writeArchiveAtomic replaces the archive file in one rename, so a crash
322	// can only expose the previous or the next complete commit, never a half
323	// written file.
324	func writeArchiveAtomic(dir string, data archiveData) error {
325		raw, err := json.MarshalIndent(data, "", "  ")
326		if err != nil {
327			return err
328		}
329		tmp := filepath.Join(dir, archiveFileName+".tmp")
330		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
331		if err != nil {
332			return err
333		}
334		if _, err := f.Write(raw); err != nil {
335			f.Close()
336			os.Remove(tmp)
337			return err
338		}
339		if err := f.Sync(); err != nil {
340			f.Close()
341			os.Remove(tmp)
342			return err
343		}
344		if err := f.Close(); err != nil {
345			os.Remove(tmp)
346			return err
347		}
348		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
349			os.Remove(tmp)
350			return err
351		}
352		if d, err := os.Open(dir); err == nil {
353			d.Sync()
354			d.Close()
355		}
356		return nil
357	}
358	
359	// lockArchive takes an flock on the archive's lock file. The lock is
360	// released automatically if the process dies, so no stale locks survive.
361	func lockArchive(dir string, how int) (*os.File, error) {
362		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
363		if err != nil {
364			return nil, err
365		}
366		if err := syscall.Flock(int(f.Fd()), how); err != nil {
367			f.Close()
368			if errors.Is(err, syscall.EWOULDBLOCK) {
369				return nil, ErrBusy
370			}
371			return nil, err
372		}
373		return f, nil
374	}
375	
376	type parsedBlock struct {
377		line  int
378		block Block
379	}
380	
381	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
382		var out []parsedBlock
383		reader := bufio.NewReader(r)
384		lineNo := 0
385		for {
386			raw, err := reader.ReadBytes('\n')
387			if len(raw) > 0 {
388				lineNo++
389			}
390			if text := strings.TrimSpace(string(raw)); text != "" {
391				block, perr := parseBlock(text)
392				if perr != nil {
393					return nil, &LineError{Line: lineNo, Err: perr}
394				}
395				out = append(out, parsedBlock{line: lineNo, block: block})
396			}
397			if err == io.EOF {
398				return out, nil
399			}
400			if err != nil {
401				return nil, err
402			}
403		}
404	}
405	
406	// ReplayFile imports the line-delimited blocks in inputPath into the
407	// archive at dir and returns one report per distinct block, in order of
408	// first appearance. New blocks are judged under the archive's currently
409	// enabled rule version.
410	func ReplayFile(inputPath, dir string) ([]Report, error) {
411		return replayFile(inputPath, dir, "")
412	}
413	
414	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
415	// version instead of the archive's enabled one.
416	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
417		if versionID == "" {
418			return nil, errors.New("version id must not be empty")
419		}
420		return replayFile(inputPath, dir, versionID)
421	}
422	
423	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
424		f, err := os.Open(inputPath)
425		if err != nil {
426			return nil, err
427		}
428		defer f.Close()
429		return doReplay(f, dir, versionID)
430	}
431	
432	// Replay parses, validates and archives blocks from r under the archive's
433	// currently enabled rule version. Every line is checked before anything is
434	// written; any failure leaves the archive untouched. New reports are
435	// committed together in a single atomic write.
436	func Replay(input io.Reader, dir string) ([]Report, error) {
437		return doReplay(input, dir, "")
438	}
439	
440	// ReplayWithVersion is Replay under an explicitly registered rule version
441	// instead of the archive's enabled one.
442	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
443		if versionID == "" {
444			return nil, errors.New("version id must not be empty")
445		}
446		return doReplay(input, dir, versionID)
447	}
448	
449	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
450		parsed, err := parseBlocks(input)
451		if err != nil {
452			return nil, err
453		}
454	
455		// Collapse repeated identities within this file, keeping first
456		// appearance order; conflicting content rejects the whole file.
457		type occurrence struct {
458			block Block
459			line  int
460		}
461		order := []occurrence{}
462		firstSeen := make(map[blockID]int)
463		for _, p := range parsed {
464			id := blockID{p.block.ChainID, p.block.BlockHash}
465			if first, ok := firstSeen[id]; ok {
466				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
467					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
468						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
469				}
470				continue
471			}
472			firstSeen[id] = len(order)
473			order = append(order, occurrence{block: p.block, line: p.line})
474		}
475	
476		if err := os.MkdirAll(dir, 0o755); err != nil {
477			return nil, err
478		}
479		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
480		if err != nil {
481			return nil, err
482		}
483		defer lock.Close()
484	
485		data, err := readArchive(dir)
486		if err != nil {
487			return nil, err
488		}
489		// Resolve the version once, while the exclusive lock is held: every
490		// new block in this run is judged under the same rules even if another
491		// process enables a different version right after we finish.
492		version, err := resolveReplayVersion(data, versionID)
493		if err != nil {
494			return nil, err
495		}
496		archived := make(map[blockID]int, len(data.Records))
497		for i, rec := range data.Records {
498			archived[rec.id()] = i
499		}
500	
501		reports := make([]Report, 0, len(order))
502		changed := false
503		for _, occ := range order {
504			id := blockID{occ.block.ChainID, occ.block.BlockHash}
505			if idx, ok := archived[id]; ok {
506				rec := data.Records[idx]
507				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
508					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
509						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
510				}
511				// Identical re-import: return the original report, add nothing.
512				reports = append(reports, rec.report())
513				continue
514			}
515			rec := record{
516				ChainID:     occ.block.ChainID,
517				BlockHash:   occ.block.BlockHash,
518				BlockNumber: occ.block.BlockNumber,
519				Swaps:       occ.block.Swaps,
520				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
521				Version:     &version,
522			}
523			archived[id] = len(data.Records)
524			data.Records = append(data.Records, rec)
525			reports = append(reports, rec.report())
526			changed = true
527		}
528		if changed {
529			if err := writeArchiveAtomic(dir, data); err != nil {
530				return nil, err
531			}
532		}
533		return reports, nil
534	}
535	
536	// resolveReplayVersion picks the rule version for one replay run: the
537	// explicitly requested one, or the archive's currently enabled version.
538	func resolveReplayVersion(data archiveData, versionID string) (RuleVersion, error) {
539		if versionID != "" {
540			return findVersion(data, versionID)
541		}
542		return data.enabledVersion()
543	}
544	
545	// Query returns the archived report for one block identity. It only reads
546	// the archive; the original input file is not needed.
547	func Query(dir, chainID, blockHash string) (Report, error) {
548		if _, err := os.Stat(dir); err != nil {
549			if errors.Is(err, os.ErrNotExist) {
550				return Report{}, ErrUnknownBlock
551			}
552			return Report{}, err
553		}
554		lock, err := lockArchive(dir, syscall.LOCK_SH)
555		if err != nil {
556			return Report{}, err
557		}
558		defer lock.Close()
559	
560		data, err := readArchive(dir)
561		if err != nil {
562			return Report{}, err
563		}
564		for _, rec := range data.Records {
565			if rec.ChainID == chainID && rec.BlockHash == blockHash {
566				return rec.report(), nil
567			}
568		}
569		return Report{}, ErrUnknownBlock
570	}
