463					i, i%5+1, i%99+2)
464				// A busy archive is a valid answer to a concurrent writer; retry
465				// until the registration commits.
466				for {
467					_, _, err := RegisterVersion(dir, []byte(spec))
468					if errors.Is(err, ErrBusy) {
469						continue
470					}
471					done <- err
472					return
473				}
474			}(i)
475		}
476		for i := 0; i < 8; i++ {
477			if err := <-done; err != nil {
