	if _, err := ReplayWithVersion(strings.NewReader(reverse), dir2, "v2"); err != nil {
		t.Fatal(err)
	}
	back, err := Compare(dir2, "1", "0xmix2", BuiltinVersionID)
	if err != nil {
		t.Fatal(err)
	}
